    <div class="imgs">${img(`img/pv6-${V}-guide.png`, 'The guide, with the stations')}${img(`img/pv6-${V}-empty.png`, 'Step 1 input: the empty-room guide')}${img(`img/pv6-${V}-empty-annotated.png`, 'The empty guide annotated: stand-ins, slices, press areas, lamps')}${img(`img/pv6-${V}-furniture.png`, 'The furniture outlines')}${img(`img/pv6-${V}-place.png`, `${STEP3 ? 'Step 2' : 'The'} PLACE mask (${pct(maskShare)})`)}${img(`img/pv6-${V}-split.png`, 'The split map')}${STEP3 ? `${img(`img/pv6-${V}-guide-s2.png`, `Step 2's guide: the stations ${WITHOUT}`)}${img(`img/pv6-${V}-place3.png`, `Step 3's mask: ${S3WHAT} (${pct(share3)})`)}${img(`img/pv6-${V}-split3.png`, "Step 3's split map")}` : ''}${STEP4 ? `${img(`img/pv6-${V}-guide-s4.png`, "Step 4's guide: an overlay, transparent outside what it draws")}${img(`img/pv6-${V}-place4.png`, `Step 4's mask: the jars' tops and the dispenser's left edge (${pct(share4)})`)}${img(`img/pv6-${V}-split4.png`, "Step 4's split map")}` : ''}${img(`img/pv6-${V}-empty-regions.png`, "Colour check v4's map, empty")}${img(`img/pv6-${V}-regions.png`, "Colour check v4's map, with the stations")}</div>
